# enumerate highly-supported rectangles by target non-bg color
cands=[]
H,W=a.shape
for v in [3,4,5,7,8]:
 for r1 in range(H):
  for r2 in range(r1+1,H):
   for c1 in range(W):
    for c2 in range(c1+1,W):
     block=a[r1:r2+1,c1:c2+1]; area=block.size; cnt=np.sum(block==v)
     if cnt>=max(4,int(.70*area)) and cnt/area>=.72:
      cands.append((cnt/area,cnt,area,v,r1,r2,c1,c2))
sorted(cands,reverse=True)[:60]
